async function downloadResponse(response,filename="",expectedType=""){
 if(!response.ok){const raw=await response.text();let message=`Research API HTTP ${response.status}`;try{message=JSON.parse(raw).error||message;}catch{if(raw)message=`Research API HTTP ${response.status} returned a non-JSON error`;}throw new Error(message);}
 const type=(response.headers.get("content-type")||"").toLowerCase();
 if(type.includes("text/html"))throw new Error("Research API returned an HTML page instead of a downloadable report");
 if(expectedType&&!type.includes(expectedType.toLowerCase()))throw new Error(`Research API returned unexpected content type: ${type||"missing"}`);
 const blob=await response.blob();if(!blob.size)throw new Error("Research API returned an empty report");
 const disposition=response.headers.get("content-disposition")||"",encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i),plain=disposition.match(/filename="?([^";]+)"?/i);
 if(!filename&&encoded){try{filename=decodeURIComponent(encoded[1]);}catch{filename=encoded[1];}}if(!filename&&plain)filename=plain[1];if(!filename)filename="CreditAtlas-report";
 const url=URL.createObjectURL(blob),download=el("a");download.href=url;download.download=filename;document.body.append(download);download.click();download.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function downloadAttachment(link){if(link.dataset.downloading==="true")return;link.dataset.downloading="true";try{const expectedType=link.href.toLowerCase().endsWith(".xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"";await downloadResponse(await fetch(link.href),link.download||"",expectedType);}catch(error){notice("Không thể tải báo cáo: "+error.message,true);}finally{delete link.dataset.downloading;}}
