  [["exposure","excel","Nhập / xuất Excel","Portfolio workbook, template và review report"],["exposure","scenarios","So sánh loss scenarios","Declared PD/LGD/EAD research assumptions"],["exposure","review","Review danh mục","Owner, rationale, expiry và versioned evidence"],["exposure","ecl","Đọc ECL study","Saved conditional cashflow/recovery assumptions"],["exposure","tail","Phân tích tail risk","Saved research loss distributions và convergence"],["retail","policy","Thử policy / subgroup","Thresholds, action costs, review capacity và support"],["retail","explanations","Giải thích hồ sơ credit","Token search, đóng góp yếu tố và private export"],["retail","validation","So sánh model validation","Development metrics, uncertainty và reliability"]].forEach(([view,tab,title,description])=>entries.unshift({view,tab,title,description}));
