function countryAnnualChart(rows){
  const known=rows.filter(row=>row.value!==null);if(!known.length)return empty("Không có giá trị nguồn trong khoảng năm được chọn.");
  const w=850,h=270,left=65,right=25,top=20,bottom=40,first=Math.min(...rows.map(row=>row.year)),last=Math.max(...rows.map(row=>row.year)),low=Math.min(...known.map(row=>row.value)),high=Math.max(...known.map(row=>row.value)),pad=(high-low)*.1||1,min=low-pad,max=high+pad;
  const x=year=>left+(year-first)/Math.max(last-first,1)*(w-left-right),y=value=>h-bottom-(value-min)/(max-min)*(h-top-bottom),canvas=svg("svg",{viewBox:"0 0 "+w+" "+h,role:"img","aria-label":"Annual source observations; missing values break the line"});canvas.classList.add("chart");
  [min,(min+max)/2,max].forEach(value=>{canvas.append(svg("line",{x1:left,x2:w-right,y1:y(value),y2:y(value),class:"grid-line"}));svgText(canvas,left-8,y(value)+4,decimal(value,2),{"text-anchor":"end",class:"axis-label"});});[first,last].forEach(year=>svgText(canvas,x(year),h-10,String(year),{"text-anchor":"middle",class:"axis-label"}));
  let segment=[],previous=null;const flush=()=>{if(segment.length>1)canvas.append(svg("polyline",{points:segment.join(" "),class:"line-primary",fill:"none"}));segment=[];};rows.forEach(row=>{if(row.value===null){flush();previous=null;return;}if(previous!==null&&row.year!==previous+1)flush();segment.push(x(row.year)+","+y(row.value));previous=row.year;canvas.append(svg("circle",{cx:x(row.year),cy:y(row.value),r:3,fill:"var(--green)"}));});flush();return canvas;
}
