function calibrationChart(bins,label="Saved final-test calibration: mean predicted probability versus observed event rate"){
  const width=420,height=280,pad=42,x=v=>pad+v*(width-pad*2),y=v=>height-pad-v*(height-pad*2),chart=svg("svg",{viewBox:"0 0 "+width+" "+height,class:"chart",role:"img","aria-label":label});
  for(let i=0;i<=4;i++){const v=i/4;chart.append(svg("line",{x1:x(0),y1:y(v),x2:x(1),y2:y(v),class:"axis"}));svgText(chart,pad-8,y(v)+3,percent(v,0),{"text-anchor":"end"});svgText(chart,x(v),height-17,percent(v,0),{"text-anchor":"middle"});}
  chart.append(svg("line",{x1:x(0),y1:y(0),x2:x(1),y2:y(1),class:"calibration-reference"}));
  bins.filter(b=>num(b.mean_probability)!==null&&num(b.observed_rate)!==null).forEach(b=>{const point=svg("circle",{cx:x(Number(b.mean_probability)),cy:y(Number(b.observed_rate)),r:5,class:"calibration-point"});point.append(svg("title",{}));point.firstChild.textContent=number(b.loans)+" clients · predicted "+percent(b.mean_probability)+" · observed "+percent(b.observed_rate);chart.append(point);});return chart;
}
