  tasks.forEach(([key,label])=>{const tab=button(label,()=>select(key)),panel=el("div","task-panel");tab.id=scope+"-tab-"+key;tab.setAttribute("role","tab");tab.setAttribute("aria-controls",scope+"-panel-"+key);panel.id=scope+"-panel-"+key;panel.setAttribute("role","tabpanel");panel.setAttribute("aria-labelledby",tab.id);panel.hidden=true;panels[key]=panel;buttons[key]=tab;versions[key]=0;nav.append(tab);stage.append(panel);});
