  const panel=card("Portfolio finance / research review","Lưu nhận định cùng snapshot, owner, expiry và lịch sử phiên bản; reviewed không chứng nhận capital/ECL");panel.id="portfolio-review";section(body,panel);
  const saved=el("select");saved.setAttribute("aria-label","Portfolio saved review");panel.append(saved);let editing=null;
  const title=el("input"),owner=el("input"),expiry=el("input"),rationale=el("textarea"),status=el("select"),ack=el("input");expiry.type="date";ack.type="checkbox";rationale.rows=4;
  title.setAttribute("aria-label","Portfolio review title");owner.setAttribute("aria-label","Portfolio review owner");expiry.setAttribute("aria-label","Portfolio review expiry");rationale.setAttribute("aria-label","Portfolio review rationale");status.setAttribute("aria-label","Portfolio review status");ack.setAttribute("aria-label","Acknowledge declared assumptions");
  for(const name of ["draft","reviewed","archived"]){const option=el("option","",name);option.value=name;status.append(option);}
  const future=new Date();future.setUTCDate(future.getUTCDate()+90);expiry.value=future.toISOString().slice(0,10);
  for(const [name,input] of [["Title",title],["Owner",owner],["Expires on (UTC)",expiry],["Rationale & limitations",rationale],["Research status",status],["Tôi đã đọc các giả định chưa calibrated",ack]]){const label=el("label","review-field",name);label.append(input);panel.append(label);}
  const message=para("Evidence được pin theo phiên bản; annotation không thay source amounts hoặc model results.");panel.append(message);
  const save=el("button","button","Lưu portfolio review"),exportLink=el("a","button secondary","Xuất portfolio review");exportLink.hidden=true;panel.append(save,exportLink);
