  const global=el("div"),local=el("div"),whole=el("div");global.id="retail-explanation-global";local.id="retail-explanation-local";panel.append(global,local,whole);
  const labels={credit_limit:"Hạn mức",repayment_status:"Trạng thái trả nợ · 6 tháng",bill_history:"Hóa đơn · 6 tháng",payment_history:"Thanh toán · 6 tháng"};let epoch=0,report=null;
